"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import ArrowDown from "@/components/icons/ArrowDown"
import LinkIcon from "@/components/icons/LinkIcon"

type MediaKey =
  | "mainWebsite"
  | "mainShop"
  | "instagram"
  | "x"
  | "facebook"
  | "tumblr"
  | "pixiv"
  | "bluesky"

type Option = {
  key: MediaKey
  label: string
  recommended?: boolean
}

type Props = {
  value?: MediaKey | ""
  onChange?: (v: MediaKey) => void
  helperText?: string
  className?: string
}

const OPTIONS: Option[] = [
  { key: "mainWebsite", label: "Main Website", recommended: true },
  { key: "mainShop", label: "Main Shop", recommended: true },
  { key: "instagram", label: "Instagram", recommended: true },
  { key: "x", label: "X / Twitter" },
  { key: "facebook", label: "Facebook" },
  { key: "tumblr", label: "Tumblr" },
  { key: "pixiv", label: "Pixiv" },
  { key: "bluesky", label: "Bluesky" },
]

export default function AddedLinkMediaSelect({
  value = "",
  onChange,
  helperText = "Recommended: 1 website, 2 social media, and 1 shop",
  className = "",
}: Props) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement | null>(null)

  const selectedLabel = useMemo(() => {
    const found = OPTIONS.find((o) => o.key === value)
    return found?.label ?? ""
  }, [value])

  useEffect(() => {
    function onDocMouseDown(e: MouseEvent) {
      if (!rootRef.current) return
      if (!rootRef.current.contains(e.target as Node)) setOpen(false)
    }
    function onEsc(e: KeyboardEvent) {
      if (e.key === "Escape") setOpen(false)
    }

    document.addEventListener("mousedown", onDocMouseDown)
    document.addEventListener("keydown", onEsc)
    return () => {
      document.removeEventListener("mousedown", onDocMouseDown)
      document.removeEventListener("keydown", onEsc)
    }
  }, [])

  return (
    <div
      ref={rootRef}
      className={[
        "w-[426px] flex flex-col items-start gap-[10px]",
        className,
      ].join(" ")}
    >
      {/* Row: icon + select */}
      <div className="w-full flex flex-row items-center gap-[13px]">
        {/* Link icon */}
        <div className="w-[24px] h-[24px] flex items-center justify-center flex-shrink-0">
          <LinkIcon className="text-[#A5A5A5]" />
        </div>

        {/* Dropdown container */}
        <div className="relative w-[360px]">
          {/* Collapsed */}
          <button
            type="button"
            onClick={() => setOpen((v) => !v)}
            className={[
              "w-[360px] h-[40px]",
              "bg-white border border-[#A5A5A5]/50 rounded-[8px]",
              "px-[10px] py-[12px]",
              "flex items-center justify-between gap-[10px]",
            ].join(" ")}
          >
            <span
              className={[
                "font-inter text-[12px] leading-[140%]",
                value ? "text-[#262626]" : "text-[#A5A5A5]",
              ].join(" ")}
            >
              {value ? selectedLabel : "Select a media"}
            </span>

            {/* ArrowDown (off-black when open, gray when closed like figma states vary) */}
            <ArrowDown className={open ? "text-[#262626]" : "text-[#A5A5A5]"} />
          </button>

          {/* Expanded menu */}
          {open && (
            <div
              className={[
                "absolute left-0 top-0 z-20",
                "w-[360px] h-[273px]",
                "bg-white border border-[#A5A5A5]/50 rounded-[8px]",
                "px-[10px] py-[11px]",
                "flex flex-col gap-[11px]",
              ].join(" ")}
            >
              {/* Top row inside open menu */}
              <button
                type="button"
                onClick={() => setOpen(false)}
                className="w-[340px] h-[18px] flex items-center justify-between"
              >
                <span className="font-inter text-[12px] leading-[140%] text-[#A5A5A5]">
                  Select a media
                </span>
                <ArrowDown className="text-[#262626]" />
              </button>

              {/* Options */}
              <div className="w-[340px] flex flex-col items-start gap-[10px]">
                {OPTIONS.map((opt) => (
                  <button
                    key={opt.key}
                    type="button"
                    onClick={() => {
                      onChange?.(opt.key)
                      setOpen(false)
                    }}
                    className={[
                      "w-[340px] h-[19px]",
                      "flex items-center justify-between",
                      "px-[5px]",
                    ].join(" ")}
                  >
                    <span className="font-inter text-[12px] leading-[15px] text-[#262626]">
                      {opt.label}
                    </span>

                    {opt.recommended ? (
                      <span className="font-inter text-[9px] leading-[11px] text-[#A5A5A5]">
                        Recommended
                      </span>
                    ) : (
                      <span className="w-[64px]" aria-hidden="true" />
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Helper text */}
      <div className="w-[426px] h-[9px] flex items-center pl-[37px]">
        <span className="font-inter text-[12px] leading-[140%] text-[#A5A5A5]">
          {helperText}
        </span>
      </div>
    </div>
  )
}
